
'use strict';
renderCard=function(c){const suit={spades:'♠',hearts:'♥',diamonds:'♦',clubs:'♣'}[c.suit];return SSCardMarkup(c.rank+suit).replace('class="pc','class="card ss-unified-card')};
comboToHand=function(combo,excluded=[]){const blocked=normalizeExcludedCardCodes(excluded),all=[];for(const s1 of SUITS)for(const s2 of SUITS){if(combo[0]===combo[1]&&s1===s2)continue;if(combo.endsWith('s')&&s1!==s2)continue;if(combo.endsWith('o')&&s1===s2)continue;const h={c1:{rank:combo[0],suit:s1},c2:{rank:combo[1],suit:s2}};if(getHandCardCodes(h).every(c=>!blocked.has(c)))all.push(h)}return all.length?all[Math.floor(Math.random()*all.length)]:null};
normalizeActionFrequencies=function(f,fallback='Fold'){const v=ACTION_FREQUENCY_ORDER.map(a=>Math.max(0,Number(f?.[a])||0)),sum=v.reduce((a,b)=>a+b,0),out={};if(!sum){ACTION_FREQUENCY_ORDER.forEach(a=>out[a]=a===fallback?100:0);return out}const raw=v.map(n=>n/sum*100),base=raw.map(Math.floor),order=raw.map((n,i)=>({i,r:n-base[i]})).sort((a,b)=>b.r-a.r||a.i-b.i);for(let i=0,left=100-base.reduce((a,b)=>a+b,0);i<left;i++)base[order[i].i]++;ACTION_FREQUENCY_ORDER.forEach((a,i)=>out[a]=base[i]);return out};
getDefenseActionFrequencies=function(id,combo,scenario=null){const table=DEFENSE_ACTION_FREQUENCIES[id];if(table)return normalizeActionFrequencies(table[combo]||{Fold:100});const compact=GREENLINE_DEFENSE_ACTION_FREQUENCIES[id];if(compact)return normalizeActionFrequencies(getCompactSourceChartFrequencies(compact,combo));const sc=scenario||DEFEND_SCENARIOS[id];return getActionRangeFrequencies(combo,sc?.THREE_BET,sc?.CALL)};
getAllStreetAvailableActions=function(t){return ['CHECK_RAISE_FLOP','BLUFF_CATCH_RIVER','FACING_OVERBET'].includes(t)?['Fold','Call','Raise']:['Fold','Raise']};
getAllStreetGeneratedComboActions=function(){return {}};
const SSCustom=buildCustomAllStreetScenario;buildCustomAllStreetScenario=function(d,excluded=[]){const x=SSCustom(d,excluded);if(x.heroPosition===x.villainPosition)x.villainPosition=POSITIONS.find(p=>p!==x.heroPosition);x.comboActions={};x.ranges={};x.defaultAction=null;x.reviewStatus='exploration-only';const facing=['CHECK_RAISE_FLOP','BLUFF_CATCH_RIVER','FACING_OVERBET'].includes(x.template),p=+x.potBb,stack=+x.effectiveStackBb;x.toCallBb=facing?Math.min(p/3,stack):0;x.preBetPotBb=p-x.toCallBb;const frac=({BET_33:1/3,BET_50:.5,BET_75:.75,OVERBET:1.25})[d.raiseSizing]||1/3,bet=d.raiseSizing==='JAM'?stack:Math.min(p*frac,stack);x.actionLabels=facing?{Fold:'Fold',Call:`Call ${x.toCallBb.toFixed(2)} BB`}:{Fold:'Check',Raise:`Bet ${bet.toFixed(2)} BB (${d.raiseSizing==='JAM'?'All-in':(frac*100).toFixed(2)+'% pot'})`};x.availableActions=Object.keys(x.actionLabels);x.availableSizes=Object.values(x.actionLabels);x.spr=Number((stack/p).toFixed(4));x.previousAction=['Independent user snapshot; not a reconstructed history; no strategy score.'];return x};
evaluateAllStreet=function(h,x=getCurrentAllStreetScenario()){if(!x)return{action:null,scoreable:false,explanation:'沒有有效情境，不判分。'};const codes=getHandCardCodes(h);if(new Set([...codes,...x.boardCards]).size!==codes.length+x.boardCards.length)return{action:null,scoreable:false,explanation:'重複卡牌，不能判分。'};if(x.id==='starter_river_facing_overbet_ak6jt'&&codes.some(c=>c[0]==='Q'))return{action:'Call',scoreable:true,acceptableActions:['Call'],explanation:'A-K-6-J-T 河牌持Q可組成A-K-Q-J-T最大順子，現金桌面對全下不能棄牌；不計ICM與抽水。'};return{action:null,scoreable:false,explanation:'探索情境：沒有經驗證的策略答案。不計分、不加入錯題。請使用模型題練習明確假設下的計算。'}};
getAllStreetScenarioExplanation=function(x){return x?.explanation||'使用者自訂，不提供策略認證。'};const SSTitle=getAllStreetScenarioTitle;getAllStreetScenarioTitle=function(x,t){return x?.id==='starter_flop_checkraise_a54r'?'BB 對 BTN：輪子牌面 Check-Raise 探索':SSTitle(x,t)};
const SSPush=getPushFoldActionFrequencies;getPushFoldActionFrequencies=function(p,s,c){return p==='SB'?SSPush(p,s,c):{}};const SSPushEval=evaluatePushFold;evaluatePushFold=function(h,p){return p==='SB'?SSPushEval(h,p):{action:null,scoreable:false,explanation:'單挑SB以外不使用此參考模型判分。'}};
getPushFoldRangeSource=function(p,s,c){return p==='SB'&&Number.isFinite(CANDY_POKER_HU_SB_PUSH_THRESHOLDS[c])?{id:CANDY_POKER_HU_PUSH_FOLD_SOURCE_ID,note:`Heads-up SB only ${s} BB restricted push/fold threshold; not multiplayer or ICM.`}:getInternalBaselineSource('Unsupported HU reference position/hand; not a solver answer.')};
const SSValidate=validateCustomDrill;validateCustomDrill=function(d){const r=SSValidate(d),e=[...r.errors];if(d){for(const k of ['villainPosition','openerPosition'])if(d.heroPosition&&d[k]&&d.heroPosition===d[k]&&!isDrillRandomValue(d.heroPosition))e.push('positions-must-differ');if(d.threeBetSizeBb&&d.openSizeBb&&!isDrillRandomValue(d.openSizeBb)&&+d.threeBetSizeBb<2*(+d.openSizeBb)-1)e.push('illegal-minimum-reraise');if(d.threeBetSizeBb&&d.effectiveStackBb&&+d.threeBetSizeBb>+d.effectiveStackBb)e.push('raise-exceeds-stack')}return{valid:!e.length,errors:[...new Set(e)]}};
const SSLoad=loadFromStorage;loadFromStorage=function(){SSLoad();let old={};const raw=SSStorage.get(LS_KEY);try{old=JSON.parse(raw||'{}')}catch{}if(raw&&old.integrityVersion!==3){if(!SSStorage.set('spotsense-legacy-backup-v1',raw))return;state.stats=getDefaultStats();state.handHistory=[];state.mistakeReplay=getDefaultMistakeReplay();state.comboWeights={};state.trainingSession=null;state.focusSession=null;state.assessment=null}};
const SSSave=saveToStorage;saveToStorage=function(){SSSave();try{const d=JSON.parse(SSStorage.get(LS_KEY)||'{}');d.integrityVersion=3;SSStorage.set(LS_KEY,JSON.stringify(d))}catch{}};
const SSTable=renderTableContextOverlay;renderTableContextOverlay=function(m={}){const custom=state.currentMode==='CUSTOM'&&getActiveCustomDrill()?.type===DRILL_TYPES.ALL_STREET,x=state.currentMode==='ALL_STREET'||custom?getActiveAllStreetScenario():null;if(m.positions)m={...m,positions:m.positions.map(p=>({...p,stack:x?.remainingStacks?.[p.position]!==undefined?`${Number(x.remainingStacks[p.position].toFixed(2))} BB 剩餘`:'位置'}))};return SSTable(m)};
const SSTurn=startTurn;startTurn=function(){SSTurn();if(!state.currentHand)return;if(state.currentMode==='PUSH_FOLD'){state.currentPosition='SB';state.chartPosition='SB'}const custom=state.currentMode==='CUSTOM'&&getActiveCustomDrill()?.type===DRILL_TYPES.ALL_STREET;let x=state.currentMode==='ALL_STREET'||custom?getActiveAllStreetScenario():null;if(state.currentMode==='REVIEW'&&state.currentReviewItem?.allStreetScenario)x=state.currentReviewItem.allStreetScenario;if(x){const h=comboToHand(getComboName(state.currentHand),x.boardCards);if(h)state.currentHand=h;else{const d=getDeckCardCodes(x.boardCards);state.currentHand={c1:parseCardCode(d[0]),c2:parseCardCode(d[1])}}}holeCardsEl.innerHTML=renderCard(state.currentHand.c1)+renderCard(state.currentHand.c2);updateScenarioUI();const r=evaluateAction(state.currentHand,state.currentPosition);state.correctAction=r.action;state.currentActionFrequencies=r.actionFrequencies||null;state.currentAcceptableActions=r.acceptableActions||[];state.explanation=r.explanation;state.ssScoreable=r.scoreable!==false&&!!r.action;if(state.currentMode==='CUSTOM'&&getActiveCustomDrill()?.type===DRILL_TYPES.PUSH_FOLD&&state.currentPosition!=='SB'){state.ssScoreable=false;state.explanation='自訂多位置Push/Fold不套用單挑資料判分。'}if(state.currentMode==='REVIEW'&&getReviewSourceMode(state.currentReviewItem)==='ALL_STREET'){state.ssScoreable=false;state.explanation='舊翻牌後錯題只供探索，未重新驗證。'}if(state.currentMode==='PUSH_FOLD')renderTableContextOverlay({positions:[{role:'hero',position:'SB',label:'Hero SB'},{role:'villain',position:'BB',label:'Opponent BB'}]});updateReviewActionButtons();SSNote()};
const SSAction=window.handleAction;window.handleAction=function(a){const b={Fold:btnFoldEl,Call:btnCallEl,Raise:btnRaiseEl,'All-In':btnAllInEl}[a];if(!b||b.disabled||b.classList.contains('hidden'))return;if(state.ssScoreable===false){feedbackEl.className='feedback';feedbackTitleEl.textContent='探索回饋・不計分';feedbackIconEl.textContent='ℹ';feedbackMsgEl.textContent=state.explanation;setDecisionControlsLocked(true);return}SSAction(a)};
function SSNote(){const e=document.getElementById('ss-mode-note');if(!e)return;const m=state.currentMode,names={RFI:'首次開池',DEFEND:'面對開池',FACING_3BET:'面對再加注',ALL_STREET:'翻牌後探索',PUSH_FOLD:'單挑 SB Push/Fold',CUSTOM:'自訂練習',REVIEW:'錯題複習'};e.innerHTML=`<small>SPOTSENSE / 訓練 / ${names[m]||m}</small><h1>${names[m]||m}</h1><p>${m==='ALL_STREET'?'原21個情境已重建帳目；未驗證的策略不計分。底池含待跟注下注，SPR採該下注前時點。':m==='PUSH_FOLD'?'僅單挑SB首次入池的限定push/fold參考，不是多人、ICM或完整limp/raise策略。':'分數代表符合資料來源的可接受動作，不代表混合頻率執行正確。'}</p><div class="ss-actions"><a class="ss-link" href="learn.html?module=${m==='ALL_STREET'?6:2}">回看教學</a><a class="ss-link ss-primary" href="models.html">模型與頻率訓練 →</a></div>`}
const SSChange=window.changeMode;window.changeMode=function(...a){const r=SSChange(...a);SSNote();return r};document.addEventListener('DOMContentLoaded',()=>{const d=document.createElement('section');d.id='ss-mode-note';d.className='ss-box';document.getElementById('practice-panel').prepend(d);SSNote();for(const t of Object.values(I18N)){t.statsAccuracy='動作辨識率';t.statsOverallAccuracy='可接受動作辨識率';t.modePushFold='單挑SB Push/Fold';t.modeAllStreet='翻牌後探索（未驗證不計分）'}applyStaticI18n();const m=new URLSearchParams(location.search).get('mode');if(['RFI','DEFEND','FACING_3BET','ALL_STREET','PUSH_FOLD','CUSTOM'].includes(m)){changeMode(m,true);setActiveTab('practice')}const p=document.createElement('section');p.className='ss-box';p.innerHTML='<h2>獨立模型與頻率訓練</h2><p>21道明示數學模型題，與混合頻率執行分開記錄。</p><a class="ss-link ss-primary" href="models.html">開始練習 →</a>';document.getElementById('plan-panel').prepend(p)});
